examples.config:
Director {
  Name = "bareos-dir"
}

Director {
  Name = bareos-dir
  Description = "Main backup server"
}

Director {
  Name = bareos-dir
  Messages = "Daemon"
}

Director {
  Name = bareos-dir
  Port = 9101
}

Director {
  Name = bareos-dir
  Address = "192.0.2.10"
}

Director {
  Name = bareos-dir
  Addresses = {
    ipv4 = { addr = 0.0.0.0; port = 9101 }
    ipv6 = { addr = ::; port = 9101 }
  }
}

Director {
  Name = bareos-dir
  Source Address = "192.0.2.10"
}

Director {
  Name = bareos-dir
  Query File = "/usr/lib/bareos/scripts/query.sql"
}

Director {
  Name = bareos-dir
  Working Directory = "/var/lib/bareos"
}

Director {
  Name = bareos-dir
  Plugin Directory = "/usr/lib/bareos/plugins"
}

Director {
  Name = bareos-dir
  Plugin Names = "python3"
}

Director {
  Name = bareos-dir
  Scripts Directory = "/usr/lib/bareos/scripts"
}

Director {
  Name = bareos-dir
  Subscriptions = 50
}

Director {
  Name = bareos-dir
  Maximum Concurrent Jobs = 20
}

Director {
  Name = bareos-dir
  Maximum Console Connections = 20
}

Director {
  Name = bareos-dir
  Password = "secret"
}

Director {
  Name = bareos-dir
  FD Connect Timeout = 3 minutes
}

Director {
  Name = bareos-dir
  SD Connect Timeout = 30 minutes
}

Director {
  Name = bareos-dir
  Heartbeat Interval = 60
}

Director {
  Name = bareos-dir
  Statistics Retention = 5 years
}

Director {
  Name = bareos-dir
  Statistics Collect Interval = 0
}

Director {
  Name = bareos-dir
  Ver Id = "site A"
}

Director {
  Name = bareos-dir
  Key Encryption Key = "long-random-string"
}

Director {
  Name = bareos-dir
  NDMP Snooping = no
}

Director {
  Name = bareos-dir
  NDMP Log Level = 4
}

Director {
  Name = bareos-dir
  NDMP Namelist Fhinfo Set Zero For Invalid Uquad = no
}

Director {
  Name = bareos-dir
  Absolute Job Timeout = 0
}

Director {
  Name = bareos-dir
  Auditing = yes
}

Director {
  Name = bareos-dir
  Audit Events = "label, purge, delete, configure"
}

Director {
  Name = bareos-dir
  Secure Erase Command = "/usr/bin/shred -u"
}

Director {
  Name = bareos-dir
  Log Timestamp Format = "%Y-%m-%d %H:%M:%S"
}

Director {
  Name = bareos-dir
  Enable kTLS = no
}

Director {
  Name = bareos-dir
  TLS Authenticate = no
}

Director {
  Name = bareos-dir
  TLS Enable = yes
}

Director {
  Name = bareos-dir
  TLS Require = yes
}

Director {
  Name = bareos-dir
  TLS Cipher List = "PSK-AES256-GCM-SHA384:PSK-AES128-GCM-SHA256"
}

Director {
  Name = bareos-dir
  TLS Cipher Suites = "TLS_AES_256_GCM_SHA384:TLS_CHACHA20_POLY1305_SHA256"
}

Director {
  Name = bareos-dir
  TLS DH File = "/etc/bareos/tls/dh2048.pem"
}

Director {
  Name = bareos-dir
  TLS Protocol = "-ALL, +TLSv1.2, +TLSv1.3"
}

Director {
  Name = bareos-dir
  TLS Verify Peer = yes
}

Director {
  Name = bareos-dir
  TLS Ca Certificate File = "/etc/bareos/tls/ca.pem"
}

Director {
  Name = bareos-dir
  TLS Ca Certificate Dir = "/etc/ssl/certs"
}

Director {
  Name = bareos-dir
  TLS Certificate Revocation List = "/etc/bareos/tls/crl.pem"
}

Director {
  Name = bareos-dir
  TLS Certificate = "/etc/bareos/tls/bareos-dir.pem"
}

Director {
  Name = bareos-dir
  TLS Key = "/etc/bareos/tls/bareos-dir.key"
}

Director {
  Name = bareos-dir
  TLS Allowed CN = "client1.example.com"
}

Director {
  Name = bareos-dir
  Grpc Port = 10101
}

Director {
  Name = bareos-dir
  Grpc Tls Certificate = "/etc/bareos/tls/grpc.pem"
}

Director {
  Name = bareos-dir
  Grpc Tls Key = "/etc/bareos/tls/grpc.key"
}

Director {
  Name = bareos-dir
  Mdns Advertise = no
}
